// site.mjs — fixture site for tests/e2e.sh: the cases a capture must get right (POST→302 with Set-Cookie,
// JSON XHR, a link to a new tab). Usage: node tests/fixtures/site.mjs <port>
import { createServer } from 'node:http';
const port = +process.argv[2];

// A minimal valid one-page PDF with one line of text (xref offsets computed): what tandem-pdf must save
// as is when a tab shows it. `pad` bytes of comment after the header make a big one that is still valid.
export function pdf(text, pad = 0) {
  const stream = `BT /F1 18 Tf 20 100 Td (${text}) Tj ET`;
  const objs = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>',
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ];
  let out = `%PDF-1.4\n${pad ? `%${'x'.repeat(pad)}\n` : ''}`; const offs = [];
  objs.forEach((o, i) => { offs.push(out.length); out += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n${offs.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('')}`;
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, 'latin1');
}
createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  if (req.method === 'POST' && u.pathname === '/submit') {
    let body = ''; req.on('data', (c) => (body += c)); req.on('end', () => {
      res.writeHead(302, { Location: `/done?saved=${new URLSearchParams(body).get('name')}`, 'Set-Cookie': 'sid=abc123; Path=/' });
      res.end();
    });
    return;
  }
  // a PDF by GET (in the HTTP cache) and one only a POST returns (in no cache; GET gives HTML)
  if (u.pathname === '/doc.pdf') { res.writeHead(200, { 'Content-Type': 'application/pdf' }); res.end(pdf('Hello tandem')); return; }
  // not kept in the HTTP cache: tandem-pdf has to fetch it again
  if (u.pathname === '/nostore.pdf') { res.writeHead(200, { 'Content-Type': 'application/pdf', 'Cache-Control': 'no-store' }); res.end(pdf('Hello tandem')); return; }
  if (u.pathname === '/download-pdf') { res.writeHead(200, { 'Content-Type': 'application/octet-stream', 'Content-Disposition': 'attachment; filename="factura 7.pdf"' }); res.end(pdf('Downloaded')); return; }
  // blob: PDFs made by the page (same tab, new tab), a PDF framed inside a cross-origin iframe, and a page
  // that calls tandem's capture binding with forged data (pdf-capture-e2e.mjs)
  if (u.pathname === '/pdf-blob') {
    const b64 = pdf('Blob PDF').toString('base64');
    const mk = `window.URL.createObjectURL(new Blob([Uint8Array.from(atob('${b64}'), (c) => c.charCodeAt(0))], { type: 'application/pdf' }))`;
    res.writeHead(200, { 'Content-Type': 'text/html' });
    // untyped and big (4 MB, valid), navigated to at once: an async sniff loses that race (measured)
    const big = `window.URL.createObjectURL(new Blob([Uint8Array.from(atob('${pdf('Big untyped', 4194304).toString('base64')}'), (c) => c.charCodeAt(0))]))`;
    res.end(`<button onclick="window.open(${mk})">New tab</button><button onclick="location.href = ${mk}">Same tab</button><button onclick="location.href = ${big}">Big untyped</button>`);
    return;
  }
  if (u.pathname === '/frame-outer') { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(`<iframe src="http://localhost:${port}/frame-inner"></iframe>`); return; }
  if (u.pathname === '/frame-inner') { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end('<iframe src="/nested.pdf"></iframe>'); return; }
  if (u.pathname === '/nested.pdf') { res.writeHead(200, { 'Content-Type': 'application/pdf' }); res.end(pdf('Nested')); return; }
  if (u.pathname === '/forge') {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(`<script>if (typeof __tandemPdf === 'function') { __tandemPdf(JSON.stringify({ url: 'blob:http://evil.example/../../x', b64: btoa('%PDF-1.4 x') })); __tandemPdf(JSON.stringify({ url: 'blob:http://evil.example/4254c526-8257-4c1e-9b8a-1f2e3d4c5b6a', b64: btoa('<html>not a pdf') })); __tandemPdf('not json'); }</script>forge`);
    return;
  }
  if (u.pathname === '/pdf-start') { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end('<h1>PDFs</h1><form method="post" action="/gen-pdf"><button>Generate</button></form><a href="/download-pdf">Download</a>'); return; }
  if (req.method === 'POST' && u.pathname === '/gen-pdf') { res.writeHead(200, { 'Content-Type': 'application/pdf' }); res.end(pdf('Generated by POST')); return; }
  if (u.pathname === '/api') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end('{"ok":true,"n":3}'); return; }
  // as raw.githubusercontent.com serves every file: the page can run no script (sandbox-guard.mjs)
  if (u.pathname === '/sandboxed') {
    res.writeHead(200, { 'Content-Type': 'text/plain', 'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; sandbox" });
    res.end('# README\nplain text');
    return;
  }
  res.writeHead(200, { 'Content-Type': 'text/html' });
  // a button to click from a background tab (focus-e2e.mjs)
  if (u.pathname === '/focus') { res.end(`<button onclick="document.title='clicked'">Go</button>`); return; }
  if (u.pathname === '/') {
    res.end(`<h1>Home</h1><form method="post" action="/submit"><input name="name" placeholder="Name"><button>Save</button></form>
      <a href="/newtab" target="_blank">Open new tab</a><script>fetch('/api')</script>`);
  } else res.end(`<h1>${u.pathname}</h1>`);
}).listen(port, '127.0.0.1');
